INSERT INTO `wp_postmeta` VALUES (828,2,'_elementor_data','[{\"id\":\"2768432d\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"6e84ee0\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<!-- wp:paragraph -->\\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:quote -->\\n<blockquote class=\\\"wp-block-quote\\\"><p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)<\\/p><\\/blockquote>\\n<!-- \\/wp:quote -->\\n\\n<!-- wp:paragraph -->\\n<p>...or something like this:<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:quote -->\\n<blockquote class=\\\"wp-block-quote\\\"><p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.<\\/p><\\/blockquote>\\n<!-- \\/wp:quote -->\\n\\n<!-- wp:paragraph -->\\n<p>As a new WordPress user, you should go to <a href=\\\"http:\\/\\/salem-events-hub-discover-local-happenings.local\\/wp-admin\\/\\\">your dashboard<\\/a> to delete this page and create new pages for your content. Have fun!<\\/p>\\n<!-- \\/wp:paragraph -->\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false},{\"id\":\"a958bd5\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"fdea40b\",\"elType\":\"widget\",\"settings\":{\"before_text\":\"This page is\",\"highlighted_text\":\"Amazing\",\"rotating_text\":\"Better\\nBigger\\nFaster\"},\"elements\":[],\"widgetType\":\"animated-headline\"}],\"isInner\":false}]');
