alendar-frame {rn        width: 100%;rn        height: 600px;rn        border: none;rn        border-radius: 10px;rn        overflow: hidden;rn    }rnrn    /* Prevent layout shift or extra spacing issues */rn    .wp-block-group, .wp-block-column {rn        overflow: hidden;rn    }rnrn    /* Responsive Fixes */rn    @media (max-width: 768px) {rn        .calendar-container {rn            padding: 10px;rn        }rn        rn        .calendar-frame {rn            height: 500px;rn        }rn    }rnrn    @media (max-width: 480px) {rn        .calendar-frame {rn            height: 450px;rn        }rn    }rn</style>rnrn<!-- Calendar Embed -->rn<div class=\"calendar-container\">rn    <div class=\"calendar-title\">ud83dudcc5 Upcoming Events</div>rn    <iframe class=\"calendar-frame\" src=\"https://calendar.google.com/calendar/embed?src=024644856d6ce196b325d729d1a86f3b46e47080de04e38ddc0fe5ecb018f050%40group.calendar.google.com&ctz=America%2FNew_York\" frameborder=\"0\" scrolling=\"no\"></iframe>rn</div>rntttt</div>ntttt</div>nttttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element-78279f5e e-flex e-con-boxed e-con e-parent\" data-id=\"78279f5e\" data-element_type=\"container\">nttttt<div class=\"e-con-inner\">ntttt<div class=\"elementor-element elementor-element-5c131bd elementor-headline--style-highlight elementor-widget elementor-widget-animated-headline\" data-id=\"5c131bd\" data-element_type=\"widget\" data-settings=\"{&quot;highlighted_text&quot;:&quot;Get Involved!&quot;,&quot;marker&quot;:&quot;double_underline&quot;,&quot;headline_style&quot;:&quot;highlight&quot;,&quot;loop&quot;:&quot;yes&quot;,&quot;highlight_animation_duration&quot;:1200,&quot;highlight_iteration_delay&quot;:8000}\" data-widget_type=\"animated-headline.default\">ntttt<div class=\"elementor-widget-container\">nttttttt<h3 class=\"elementor-headline\">ntttt<span class=\"elementor-headline-dynamic-wrapper elementor-headline-text-wrapper\">nttttt<span class=\"elementor-headline-dynami