pe=\"widget\" data-widget_type=\"html.default\">ntttt<div class=\"elementor-widget-container\">nttttt<style>rn    /* Container to keep the calendar centered and styled */rn    .calendar-container {rn        max-width: 850px;rn        margin: 20px auto; /* Adds space from the top */rn        background: white;rn        padding: 15px;rn        border-radius: 12px;rn        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.1);rn        transition: transform 0.3s ease, box-shadow 0.3s ease;rn    }rnrn    /* Hover effect for a slight lift */rn    .calendar-container:hover {rn        transform: scale(1.02);rn        box-shadow: 0px 6px 15px rgba(0, 0, 0, 0.2);rn    }rnrn    /* Title style */rn    .calendar-title {rn        font-size: 22px;rn        font-weight: bold;rn        color: #333;rn        text-align: center;rn        margin-bottom: 10px;rn    }rnrn    /* Calendar iframe styling */rn    .calendar-frame {rn        width: 100%;rn        height: 600px;rn        border: none;rn        border-radius: 10px;rn        overflow: hidden;rn    }rnrn    /* Prevent layout shift or extra spacing issues */rn    .wp-block-group, .wp-block-column {rn        overflow: hidden;rn    }rnrn    /* Responsive Fixes */rn    @media (max-width: 768px) {rn        .calendar-container {rn            padding: 10px;rn        }rn        rn        .calendar-frame {rn            height: 500px;rn        }rn    }rnrn    @media (max-width: 480px) {rn        .calendar-frame {rn            height: 450px;rn        }rn    }rn</style>rnrn<!-- Calendar Embed -->rn<div class=\"calendar-container\">rn    <div class=\"calendar-title\">ud83dudcc5 Upcoming Events</div>rn    <iframe class=\"calendar-frame\" src=\"https://calendar.google.com/calendar/embed?src=024644856d6ce196b325d729d1a86f3b46e47080de04e38ddc0fe5ecb018f050%40group.calendar.google.com&ctz=America%2FNew_York\" frameborder=\"0\" scrolling=\"no\"></iframe>rn</div>rntttt</div>ntttt</div>nttttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element