Event Calendar<\\/h3>\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t<div class=\\\"elementor-element elementor-element-497106a e-flex e-con-boxed e-con e-parent\\\" data-id=\\\"497106a\\\" data-element_type=\\\"container\\\">\\n\\t\\t\\t\\t\\t<div class=\\\"e-con-inner\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-bb255b0 elementor-widget elementor-widget-html\\\" data-id=\\\"bb255b0\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"html.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t<style>\\r\\n    \\/* Container to keep the calendar centered and styled *\\/\\r\\n    .calendar-container {\\r\\n        max-width: 850px;\\r\\n        margin: 20px auto; \\/* Adds space from the top *\\/\\r\\n        background: white;\\r\\n        padding: 15px;\\r\\n        border-radius: 12px;\\r\\n        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.1);\\r\\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\\r\\n    }\\r\\n\\r\\n    \\/* Hover effect for a slight lift *\\/\\r\\n    .calendar-container:hover {\\r\\n        transform: scale(1.02);\\r\\n        box-shadow: 0px 6px 15px rgba(0, 0, 0, 0.2);\\r\\n    }\\r\\n\\r\\n    \\/* Title style *\\/\\r\\n    .calendar-title {\\r\\n        font-size: 22px;\\r\\n        font-weight: bold;\\r\\n        color: #333;\\r\\n        text-align: center;\\r\\n        margin-bottom: 10px;\\r\\n    }\\r\\n\\r\\n    \\/* Calendar iframe styling *\\/\\r\\n    .calendar-frame {\\r\\n        width: 100%;\\r\\n        height: 600px;\\r\\n        border: none;\\r\\n        border-radius: 10px;\\r\\n        overflow: hidden;\\r\\n    }\\r\\n\\r\\n    \\/* Prevent layout shift or extra spacing issues *\\/\\r\\n    .wp-block-group, .wp-block-column {\\r\\n        overflow: hidden;\\r\\n    }\\r\\n\\r\\n    \\/* Responsive Fixes *\\/\\r\\n    @media (max-width: 768px) {\\r\\n        .calendar-container {\\r\\n            padding: 10px;\\r\\n        }\\r\\n        \\r\\n        .calendar-frame {\\r\\n            height: 500px;\\r\\n        }\\r\\n    }\\r\\n\\r\\n    @media (max-width: 480px) {\\r\\n        .calendar-frame {\\r\\n            height: 450px;\\r\\n        }\\r\\n    }\\r\\n<\\/style>\\r\\n\\r\\n<!-- Calendar Embed -->\\r\\n<div class=\\\"calendar-container\\\">\\r\\n    <div class=\\\"calendar-title\\\">\\ud83d\\udcc5 Upcoming Events<\\/div>\\r\\n    <iframe class=\\\"calendar-frame\\\" src=\\\"https:\\/\\/calendar.google.com\\/calendar\\/embed?src=024644856d6ce196b325d729d1a86f3b46e47080de04e38ddc0fe5ecb018f050%40group.calendar.google.com&ctz=America%2FNew_York\\\" frameborder=\\\"0\\\" scrolling=\\\"no\\\"><\\/iframe>\\r\\n<\\/div>\\r\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t<div class=\\\"elementor-element elementor-element-f3ca4dc e-flex e-con-boxed e-con e-parent\\\" data-id=\\\"f3ca4dc\\\" data-element_type=\\\"container\\\" data-settings=\\\"{&quot;background_background&quot;:&quot;gradient&quot;}\\\">\\n\\t\\t\\t\\t\\t<div class=\\\"e-con-inner\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-d70d89c elementor-widget elementor-widget-google_maps\\\" data-id=\\\"d70d89c\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"google_maps.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t\\t\\t<div class=\\\"elementor-custom-embed\\\">\\n\\t\\t\\t<iframe loading=\\\"lazy\\\"\\n\\t\\t\\t\\t\\tsrc=\\\"https:\\/\\/maps.google.com\\/maps?q=%20Where%20O%27Keefe%20Complex%2C%20O%27Keefe%20Campus%20225%20Canal%20Street%2C%20Salem%2C%20MA%2001970%20Multipurpose%20Gym&#038;t=m&#038;z=10&#038;output=embed&#038;iwloc=near\\\"\\n\\t\\t\\t\\t\\ttitle=\\\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal Street, Salem, MA 01970 Multipurpose Gym\\\"\\n\\t\\t\\t\\t\\taria-label=\\\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal St