me styling */rn    .calendar-frame {rn        width: 100%;rn        height: 600px;rn        border: none;rn        border-radius: 10px;rn        overflow: hidden;rn    }rnrn    /* Prevent layout shift or extra spacing issues */rn    .wp-block-group, .wp-block-column {rn        overflow: hidden;rn    }rnrn    /* Responsive Fixes */rn    @media (max-width: 768px) {rn        .calendar-container {rn            padding: 10px;rn        }rn        rn        .calendar-frame {rn            height: 500px;rn        }rn    }rnrn    @media (max-width: 480px) {rn        .calendar-frame {rn            height: 450px;rn        }rn    }rn</style>rnrn<!-- Calendar Embed -->rn<div class=\"calendar-container\">rn    <div class=\"calendar-title\">ud83dudcc5 Upcoming Events</div>rn    <iframe class=\"calendar-frame\" src=\"https://calendar.google.com/calendar/embed?src=024644856d6ce196b325d729d1a86f3b46e47080de04e38ddc0fe5ecb018f050%40group.calendar.google.com&ctz=America%2FNew_York\" frameborder=\"0\" scrolling=\"no\"></iframe>rn</div>rntttt</div>ntttt</div>nttttt</div>ntttt</div>ntt<div class=\"elementor-element elementor-element-f3ca4dc e-flex e-con-boxed e-con e-parent\" data-id=\"f3ca4dc\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;gradient&quot;}\">nttttt<div class=\"e-con-inner\">ntttt<div class=\"elementor-element elementor-element-d70d89c elementor-widget elementor-widget-google_maps\" data-id=\"d70d89c\" data-element_type=\"widget\" data-widget_type=\"google_maps.default\">ntttt<div class=\"elementor-widget-container\">nttttttt<div class=\"elementor-custom-embed\">nttt<iframe loading=\"lazy\"ntttttsrc=\"https://maps.google.com/maps?q=%20Where%20O%27Keefe%20Complex%2C%20O%27Keefe%20Campus%20225%20Canal%20Street%2C%20Salem%2C%20MA%2001970%20Multipurpose%20Gym&#038;t=m&#038;z=10&#038;output=embed&#038;iwloc=near\"nttttttitle=\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal Street, Salem, MA 01970 Multipurpose Gym\"ntttttaria