a-id=\\\"1516e7f3\\\" data-element_type=\\\"container\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-511aafa6 elementor-widget elementor-widget-image\\\" data-id=\\\"511aafa6\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"image.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<img width=\\\"800\\\" height=\\\"800\\\" src=\\\"http:\\/\\/salem-events-hub-discover-local-happenings.local\\/wp-content\\/uploads\\/2025\\/02\\/listeventspic.png\\\" class=\\\"attachment-large size-large wp-image-424\\\" alt=\\\"\\\" srcset=\\\"http:\\/\\/salem-events-hub-discover-local-happenings.local\\/wp-content\\/uploads\\/2025\\/02\\/listeventspic.png 1024w, http:\\/\\/salem-events-hub-discover-local-happenings.local\\/wp-content\\/uploads\\/2025\\/02\\/listeventspic-300x300.png 300w, http:\\/\\/salem-events-hub-discover-local-happenings.local\\/wp-content\\/uploads\\/2025\\/02\\/listeventspic-150x150.png 150w, http:\\/\\/salem-events-hub-discover-local-happenings.local\\/wp-content\\/uploads\\/2025\\/02\\/listeventspic-768x768.png 768w\\\" sizes=\\\"(max-width: 800px) 100vw, 800px\\\" \\/>\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t<div class=\\\"elementor-element elementor-element-09d3b09 e-flex e-con-boxed e-con e-parent\\\" data-id=\\\"09d3b09\\\" data-element_type=\\\"container\\\">\\n\\t\\t\\t\\t\\t<div class=\\\"e-con-inner\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-e1f9e36 elementor-widget elementor-widget-spacer\\\" data-id=\\\"e1f9e36\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"spacer.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t\\t\\t<div class=\\\"elementor-spacer\\\">\\n\\t\\t\\t<div class=\\\"elementor-spacer-inner\\\"><\\/div>\\n\\t\\t<\\/div>\\n\\t\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t<div class=\\\"elementor-element elementor-element-320c004 e-flex e-con-boxed e-con e-parent\\\" data-id=\\\"320c004\\\" data-element_type=\\\"container\\\">\\n\\t\\t\\t\\t\\t<div class=\\\"e-con-inner\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-3c5ec3c elementor-widget elementor-widget-heading\\\" data-id=\\\"3c5ec3c\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"heading.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t<h3 class=\\\"elementor-heading-title elementor-size-default\\\">View Our Event Calendar<\\/h3>\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t<div class=\\\"elementor-element elementor-element-497106a e-flex e-con-boxed e-con e-parent\\\" data-id=\\\"497106a\\\" data-element_type=\\\"container\\\">\\n\\t\\t\\t\\t\\t<div class=\\\"e-con-inner\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-bb255b0 elementor-widget elementor-widget-html\\\" data-id=\\\"bb255b0\\\" data-element_type=\\\"widget\\\" data-widget_type=\\\"html.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t<style>\\r\\n    \\/* Container to keep the calendar centered and styled *\\/\\r\\n    .calendar-container {\\r\\n        max-width: 850px;\\r\\n        margin: 20px auto; \\/* Adds space from the top *\\/\\r\\n        background: white;\\r\\n        padding: 15px;\\r\\n        border-radius: 12px;\\r\\n        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.1);\\r\\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\\r\\n    }\\r\\n\\r\\n    \\/* Hover effect for a slight lift *\\/\\r\\n    .calendar-container:hover {\\r\\n        transform: scale(1.02);\\r\\n        box-shadow: 0px 6px 15px rgba(0, 0, 0, 0.2);\\r\\n    }\\r\\n\\r\\n    \\/* Title style *\\/\\r\\n    .calendar-title {\\r\\n        font-size: 22px;\\r\\n        font-weight: bold;\\r\\n        color: #333;\\r\\n        text-align: center;\\r\\n        margin-bottom: 10px;\\r\\n    }\\r\\n\\r\\n    \\/* Calendar iframe styling *\\/\\r\\n    .calendar-frame {\\r\\n        width: 100%;\\r\\n        height: 600px;\\r\\n        border: none;\\r\\n        border-radius: 10px;\\r\\n        overflow: hidden;\\r\\n    }\\r\\n\\r\\n    \\/* Prevent layout shift or extra spacing issues *\\/\\r\\n    .wp-block-group, .wp-block-column {\\r\\n        overflow: hidden;\\r\\n    }\\r\\n\\r\\n    \\/* Responsive Fixes *\\/\\r\\n    @media (max-width: 768px) {\\r\\n        .calendar-container {\\r\\n            padding: 10px;\\r\\n        }\\r\\n        \\r\\n        .calendar-frame {\\r\\n            height: 500px;\\r\\n        }\\r\\n    }\\r\\n\\r\\n    @media (max-width: 480px) {\\r\\n        .calendar-frame {\\r\\n            height: 450px;\\r\\n        }\\r\\n    }\\r\\n<\\/style>\\r\\n\\r\\n<!-- Calendar Embed -->\\r\\n<div class=\\\"calendar-container\\\">\\r\\n    <div class=\\\"calendar-title\\\">\\ud83d\\udcc5 Upcoming Events<\\/div>\\r\\n    <iframe class=\\\"calendar-frame\\\" src=\\\"https:\\/\\/calendar.google.com\\/calendar\\/embed?src=024644856d6ce196b325d729d1a86f3b46e47080de04e38ddc0fe5ecb018f050%40group.calendar.google.com&ctz=America%2FNew_York\\\" frameborder=\\\"0\\\" scrolling=\\\"no\\\"><\\/iframe>\\r\\n<\\/div>\\r\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\",\"scripts\":[],\"styles\":[]}}');
INSERT INTO `wp_posts` VALUES (1,1,'2025-02-06 22:43:23','2025-02-06 22:43:23','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2025-02-06 22:43:23','2025-02-06 22:43:23','',0,'http://salem-events-hub-discover-local-happenings.local/?p=1',0,'post','',1);
INSERT INTO `wp_posts` VALUES (2,1,'2025-02-06 22:43:23','2025-02-06 22:43:23','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n<!-- wp:quote -->\n<blockquote><p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p></blockquote>\n<!-- /wp:quote -->\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n<!-- wp:quote -->\n<blockquote><p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p></blockquote>\n<!-- /wp:quote -->\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://salem-events-hub-discover-local-happenings.local/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->		\n							<h3>\n					This page is\n					Amazing\n				</h3>','Sample Page','','publish','closed','open','','sample-page','','','2025-02-19 22:20:05','2025-02-19 22:20:05','',0,'http://salem-events-hub-discover-local-happenings.local/?page_id=2',6,'page','',0);
INSERT INTO `wp_posts` VALUES (3,1,'2025-02-06 22:43:23','2025-02-06 22:43:23','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://salem-events-hub-discover-local-happenings.local.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2025-02-06 22:43:23','2025-02-06 22:43:23','',0,'http://salem-events-hub-discover-local-happenings.local/?page_id=3',5,'page','',0);
