":{\"margin\":{\"right\":\"-5vw\",\"left\":\"-5vw\"}}}} -->\n<figure class=\"wp-block-image alignright size-full is-resized\" style=\"margin-right:-5vw;margin-left:-5vw\"><img src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/themes/twentytwentyfive/assets/images/grid-flower-2.webp\" alt=\"Black and white photography close up of a flower.\" style=\"width:202px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-right:0;padding-left:0;flex-basis:50%\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-text-annotation\"} -->\n<h2 class=\"wp-block-heading is-style-text-annotation\">About Us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"className\":\"is-style-text-annotation\"} -->\n<h2 class=\"wp-block-heading is-style-text-annotation\">About Us</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"className\":\"is-style-text-subtitle\"} -->\n<p class=\"is-style-text-subtitle\">\n			<strong>Fleurs</strong> is a flower delivery and subscription business. Based in the EU, our mission is not only to deliver stunning flower arrangements across but also foster knowledge and enthusiasm on the beautiful gift of nature: flowers.			</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"is-style-section-1\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull is-style-section-1\" style=\"marg