mg src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/themes/twentytwentyfive/assets/images/delphinium-flowers.webp\" alt=\"Image for service\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Assemble</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Like flowers that bloom in unexpected places, every story unfolds with beauty and resilience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"aspectRatio\":\"4/3\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"24px\"}}}} -->\n<figure class=\"wp-block-image size-full\" style=\"margin-bottom:24px\"><img src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/themes/twentytwentyfive/assets/images/star-thristle-flower.webp\" alt=\"Image for service\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Deliver</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Like flowers that bloom in unexpected places, every story unfolds with beauty and resilience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"},\"spacing\":{\"blockGap\":\"var:preset|spacing|60\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\",\"verticalAlignment\":\"space-between\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:100%\"><!-- wp:heading {\"className\":\"is-style-text-annotation\",\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}},\"fontSize\":\"x-small\"} -->\n<h2 class=\"wp-block-heading is-style-text-annotation has-x-small-font-size\">What people are saying</h2>\n<!-- /wp:heading -->\n\n<!-- wp:quote {\"className\":\"is-style-plain\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|50\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"}},\"fontSize\":\"x-large\"} -->\n<blockquote class=\"wp-block-quote is-style-plain has-x-large-font-size\" style=\"font-style:normal;font-weight:400\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"400px\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:paragraph {\"fontSize\":\"xx-large\"} -->\n<p class=\"has-xx-large-font-size\">“Superb product and customer service!”</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --><cite>Jo Mulligan <br><sub>Atlanta, GA</sub></cite></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:image {\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/themes/twentytwentyfive/assets/images/typewriter.webp\" alt=\"Picture of a person typing on a typewriter.\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->','Blog Home','Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.','inherit','closed','closed','','7-revision-v1','','','2025-02-12 01:02:17','2025-02-12 01:02:17','',7,'http://salem-events-hub-discover-local-happenings.local/?p=40',0,'revision','',0);
