INSERT INTO `wp_posts` VALUES (264,1,'2025-02-21 05:29:49','2025-02-21 05:29:49','<h1>Find Events In The Salem Area</h1>				\n		<p>Seamlessly browse for Salem\'s diverse events in the area</p>		\n					<a href=\"http://salem-events-hub-discover-local-happenings.local/registration/\">\n									Sign Up Today!\n					</a>\n															<img width=\"800\" height=\"800\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun.webp\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun.webp 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun-300x300.webp 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun-150x150.webp 150w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun-768x768.webp 768w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n															<img width=\"800\" height=\"574\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-1024x735.jpg\" alt=\"logo\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-1024x735.jpg 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-300x215.jpg 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-768x551.jpg 768w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo.jpg 1317w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n															<img width=\"683\" height=\"600\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1.jpeg\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1.jpeg 683w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1-300x264.jpeg 300w\" sizes=\"(max-width: 683px) 100vw, 683px\" />															\n															<img width=\"683\" height=\"600\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1.jpeg\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1.jpeg 683w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1-300x264.jpeg 300w\" sizes=\"(max-width: 683px) 100vw, 683px\" />															\n															<img width=\"683\" height=\"600\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1.jpeg\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1.jpeg 683w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about-1-300x264.jpeg 300w\" sizes=\"(max-width: 683px) 100vw, 683px\" />															\n					<h3>About Us</h3>				\n		<p><strong>Welcome to Salem Events Hub: Discover Local Happenings, your go-to platform for exploring events and activities at Salem State University and beyond! Whether you\'re a student, faculty member, or local community member, our mission is to keep you informed and engaged with the vibrant campus life and surrounding events.</strong></p>		\n					<a href=\"#\">\n									Learn more\n					</a>\n					<h3>Our Services</h3>				\n					<p>This text briefly introduces visitors to your main services.</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"683\" height=\"600\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about.jpeg\" alt=\"\" /></a></figure><h4><a href=\"#\">Effortless Event Discovery</a></h4><p>Use our event finder to quickly find events that interest you!</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"683\" height=\"600\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about.jpeg\" alt=\"\" /></a></figure><h4><a href=\"#\">List Your Events</a></h4><p>List your event with us for FREE!</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/elementor/thumbs/googlecalendarandmaps-r1tgd53vll2pcd03cgdn5y3n15dc3tb8tmnd2136gm.webp\" title=\"googlecalendarandmaps\" alt=\"googlecalendarandmaps\" loading=\"lazy\" /></a></figure><h4><a href=\"#\">Google Calendar & Google Maps Integration</a></h4><p>Keep track of events and find your way there effortlessly.\n</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"683\" height=\"600\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image_Placeholder-about.jpeg\" alt=\"\" /></a></figure><h4><a href=\"#\">Event Alerts</a></h4><p>Receive alerts about upcoming events!</p>				\n			<iframe loading=\"lazy\"\n					src=\"https://maps.google.com/maps?q=%20Where%20O%27Keefe%20Complex%2C%20O%27Keefe%20Campus%20225%20Canal%20Street%2C%20Salem%2C%20MA%2001970%20Multipurpose%20Gym&#038;t=m&#038;z=10&#038;output=embed&#038;iwloc=near\"\n					title=\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal Street, Salem, MA 01970 Multipurpose Gym\"\n					aria-label=\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal Street, Salem, MA 01970 Multipurpose Gym\"\n			></iframe>\n					<h3>Why Choose Us</h3>				\n									<h4>\n							benefit 1						\n					</h4>\n									<p>\n						A short description of the benefit.					</p>\n									<h4>\n							benefit 2						\n					</h4>\n									<p>\n						A short description of the benefit.					</p>\n									<h4>\n							benefit 3						\n					</h4>\n									<p>\n						A short description of the benefit.					</p>\n									<h4>\n							benefit 4						\n					</h4>\n									<p>\n						A short description of the benefit.					</p>\n					<h3>Client Testimonials</h3>				\n							“A testimonial from a client who benefited from your product or service. Testimonials can be a highly effective way of establishing credibility and increasing your company\'s reputation.”\n							<img width=\"63\" height=\"63\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image-Testemonials.jpeg\" alt=\"\" />						\n														Client Name\n							“A testimonial from a client who benefited from your product or service. Testimonials can be a highly effective way of establishing credibility and increasing your company\'s reputation.”\n							<img width=\"63\" height=\"63\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image-Testemonials.jpeg\" alt=\"\" />						\n														Client Name\n							“A testimonial from a client who benefited from your product or service. Testimonials can be a highly effective way of establishing credibility and increasing your company\'s reputation.”\n							<img width=\"63\" height=\"63\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/Image-Testemonials.jpeg\" alt=\"\" />						\n														Client Name\n					<h3>A Title to Turn the Visitor Into a Lead</h3>				\n		Use this short paragraph to explain how you will deliver this benefit to the visitor if they decide to work with you.		\n					<a href=\"#\">\n									Learn more\n					</a>\n															<img src=\"https://salem-events-hub-discover-local-happenings.local/wp-content/plugins/elementor/assets/images/placeholder.png\" title=\"\" alt=\"\" loading=\"lazy\" />															\n							<ul>\n							<li>\n										123-456-7890\n									</li>\n								<li>\n										123 Main Street, New York, NY 10001\n									</li>\n								<li>\n										Mon-Fri 9:00AM - 5:00PM\n									</l