INSERT INTO `wp_posts` VALUES (394,1,'2025-02-23 04:16:23','2025-02-23 04:16:23','<h1>Find Events In The Salem Area</h1>				\n		<p>Seamlessly browse for Salem\'s diverse events in the area</p>		\n					<a href=\"http://salem-events-hub-discover-local-happenings.local/registration/\">\n									Sign Up Today!\n					</a>\n															<img width=\"800\" height=\"800\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun.webp\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun.webp 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun-300x300.webp 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun-150x150.webp 150w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/havingfun-768x768.webp 768w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n															<img width=\"800\" height=\"574\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-1024x735.jpg\" alt=\"logo\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-1024x735.jpg 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-300x215.jpg 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo-768x551.jpg 768w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/sslogo.jpg 1317w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n															<img width=\"800\" height=\"800\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-3.webp\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-3.webp 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-3-300x300.webp 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-3-150x150.webp 150w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-3-768x768.webp 768w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n															<img width=\"800\" height=\"800\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-1.webp\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-1.webp 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-1-300x300.webp 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-1-150x150.webp 150w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-1-768x768.webp 768w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n															<img width=\"800\" height=\"800\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-2.webp\" alt=\"\" srcset=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-2.webp 1024w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-2-300x300.webp 300w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-2-150x150.webp 150w, http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/about-us-fun-pic-2-768x768.webp 768w\" sizes=\"(max-width: 800px) 100vw, 800px\" />															\n					<h3>About Us</h3>				\n		<p><strong>Welcome to Salem Events Hub: Discover Local Happenings, your go-to platform for exploring events and activities in the Salem area! Whether you\'re a student, faculty member, or local community member, our mission is to keep you informed and engaged with the vibrant campus life and surrounding events.</strong></p>		\n					<a href=\"#\">\n									Learn more\n					</a>\n					<h2>View Our Event Calendar</h2>				\n					<style>\n    /* Container to keep the calendar centered and styled */\n    .calendar-container {\n        max-width: 850px;\n        margin: 20px auto; /* Adds space from the top */\n        background: white;\n        padding: 15px;\n        border-radius: 12px;\n        box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.1);\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\n    }\n    /* Hover effect for a slight lift */\n    .calendar-container:hover {\n        transform: scale(1.02);\n        box-shadow: 0px 6px 15px rgba(0, 0, 0, 0.2);\n    }\n    /* Title style */\n    .calendar-title {\n        font-size: 22px;\n        font-weight: bold;\n        color: #333;\n        text-align: center;\n        margin-bottom: 10px;\n    }\n    /* Calendar iframe styling */\n    .calendar-frame {\n        width: 100%;\n        height: 600px;\n        border: none;\n        border-radius: 10px;\n        overflow: hidden;\n    }\n    /* Prevent layout shift or extra spacing issues */\n    .wp-block-group, .wp-block-column {\n        overflow: hidden;\n    }\n    /* Responsive Fixes */\n    @media (max-width: 768px) {\n        .calendar-container {\n            padding: 10px;\n        }\n        .calendar-frame {\n            height: 500px;\n        }\n    }\n    @media (max-width: 480px) {\n        .calendar-frame {\n            height: 450px;\n        }\n    }\n</style>\n<!-- Calendar Embed -->\n    📅 Upcoming Events\n    <iframe src=\"https://calendar.google.com/calendar/embed?src=024644856d6ce196b325d729d1a86f3b46e47080de04e38ddc0fe5ecb018f050%40group.calendar.google.com&ctz=America%2FNew_York\" frameborder=\"0\" scrolling=\"no\"></iframe>\n					<h3>What We Offer</h3>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"1024\" height=\"1024\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/discover-homepage-pic.webp\" alt=\"\" /></a></figure><h4><a href=\"#\">Find Events</a></h4><p>Use our event finder to quickly find events that interest you!</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"1024\" height=\"1024\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/list-events-homepage-pic.webp\" alt=\"\" /></a></figure><h4><a href=\"#\">List Your Events</a></h4><p>List your event with us for FREE!</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"1078\" height=\"1077\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/magicut_1740116341890.webp\" alt=\"\" /></a></figure><h4><a href=\"#\">Google Calendar & Google Maps Integration</a></h4><p>Keep track of events and find your way there effortlessly.\n</p>				\n					<figure><a href=\"#\" tabindex=\"-1\"><img width=\"1024\" height=\"1024\" src=\"http://salem-events-hub-discover-local-happenings.local/wp-content/uploads/2025/02/alerts-homepage-pic.webp\" alt=\"\" /></a></figure><h4><a href=\"#\">Event Alerts</a></h4><p>Receive alerts about upcoming events!</p>				\n			<iframe loading=\"lazy\"\n					src=\"https://maps.google.com/maps?q=%20Where%20O%27Keefe%20Complex%2C%20O%27Keefe%20Campus%20225%20Canal%20Street%2C%20Salem%2C%20MA%2001970%20Multipurpose%20Gym&#038;t=m&#038;z=10&#038;output=embed&#038;iwloc=near\"\n					title=\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal Street, Salem, MA 01970 Multipurpose Gym\"\n					aria-label=\" Where O&#039;Keefe Complex, O&#039;Keefe Campus 225 Canal Street, Salem, MA 01970 Multipurpose Gym\"\n			></iframe>\n							<h3>\n					Get Involved!\n				</h3>\n		<h2 style=\"font-size: 2rem; font-weight: bold; text-align: center; margin-bottom: 10px;\">\n    A Connected Community is a Thriving Community\n</h2>\n<p style=\"font-size: 1.25rem; line-height: 1.6; text-align: center;\">\n    Whether you\'re searching for an exciting club meeting, a thrilling sports game, a vibrant music festival, or an inspiring guest lecture, <strong>Salem Events Hub</strong> is your gateway to discovering, connecting, and participating.  \n    Make the most of your <strong>Salem State experience</strong> with <em>Salem Events Hub: Discover Local Happenings!</em>\n</p>\n					<a href=\"#\">\n									📍 Start Exploring Today!\n					</a>','Salem Events Hub: Discover Local Happenings','','inherit','closed','closed','','93-revision-v1','','','2025-02-23 04:16:23','2025-02-23 04:16:23','',93,'http://salem-events-hub-discover-local-happenings.local/?p=394',0,'revision','',0);
